import{_ as a,o,c as t,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"title":"Troubleshooting"},"headers":[],"relativePath":"operations/troubleshooting.md","filePath":"operations/troubleshooting.md","lastUpdated":1787839527000}'),r={name:"operations/troubleshooting.md"};function n(s,e,l,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="症狀-→-原因-→-驗證-→-處理" tabindex="-1">症狀 → 原因 → 驗證 → 處理 <a class="header-anchor" href="#症狀-→-原因-→-驗證-→-處理" aria-label="Permalink to &quot;症狀 → 原因 → 驗證 → 處理&quot;">​</a></h2><h3 id="a-ci-擋在-release-sync-check" tabindex="-1">A) CI 擋在 <code>release:sync-check</code> <a class="header-anchor" href="#a-ci-擋在-release-sync-check" aria-label="Permalink to &quot;A) CI 擋在 `release:sync-check`&quot;">​</a></h3><ul><li>症狀：<code>frontend/package.json</code> version 與最新 <code>v*</code> tag 不一致</li><li>原因：人工改版本或沒走 <code>gpr</code></li><li>驗證：<code>cd frontend &amp;&amp; npm run release:sync-check</code></li><li>處理：回到 <a href="/operations/closeout-and-versioning.html">Closeout-And-Versioning</a> 用 <code>npm run gpr</code></li></ul><h3 id="b-測試通過但-ui-不對" tabindex="-1">B) 測試通過但 UI 不對 <a class="header-anchor" href="#b-測試通過但-ui-不對" aria-label="Permalink to &quot;B) 測試通過但 UI 不對&quot;">​</a></h3><ul><li>優先 <code>npm run playwright:ui-layout --prefix frontend</code>（必須進 BottomNav shell）</li><li>再跑功能 suite：<code>playwright:bank-sync</code> / <code>carrier-sync</code> / <code>budget-pay-cycle</code></li></ul><h3 id="c-playwright-找不到-browsers" tabindex="-1">C) Playwright 找不到 browsers <a class="header-anchor" href="#c-playwright-找不到-browsers" aria-label="Permalink to &quot;C) Playwright 找不到 browsers&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright:install-browsers</span></span></code></pre></div><p>對齊 CI 的 <code>PLAYWRIGHT_BROWSERS_PATH</code>。</p><h3 id="d-android-sqlite-better-sqlite3-abi" tabindex="-1">D) Android SQLite / better-sqlite3 ABI <a class="header-anchor" href="#d-android-sqlite-better-sqlite3-abi" aria-label="Permalink to &quot;D) Android SQLite / better-sqlite3 ABI&quot;">​</a></h3><p>不要在 host install native。<code>backend &amp;&amp; npm run deploy:copy</code> 後 <strong><code>docker restart StrawMB</code></strong>。<a href="/operations/backend-deployment-and-health.html">Backend-Deployment-And-Health</a></p><h3 id="e-手機銀行同步仍是舊行為" tabindex="-1">E) 手機銀行同步仍是舊行為 <a class="header-anchor" href="#e-手機銀行同步仍是舊行為" aria-label="Permalink to &quot;E) 手機銀行同步仍是舊行為&quot;">​</a></h3><p>Web／CI 綠 ≠ 原生已修。確認 APK versionName 後重裝。<a href="/operations/android-native-bank-apk.html">Android-Native-Bank-APK</a></p><h3 id="f-載具「已設定」但一查就-401-503" tabindex="-1">F) 載具「已設定」但一查就 401／503 <a class="header-anchor" href="#f-載具「已設定」但一查就-401-503" aria-label="Permalink to &quot;F) 載具「已設定」但一查就 401／503&quot;">​</a></h3><p><code>isEInvoiceApiConfigured()</code> 必須有 API base <strong>且</strong> client key，不能只因 PROD／native 就回 true。Health 200 ≠ 財政部登入成功。</p><h3 id="g-共同帳本-cors-cookie-冷啟動" tabindex="-1">G) 共同帳本 CORS／cookie 冷啟動 <a class="header-anchor" href="#g-共同帳本-cors-cookie-冷啟動" aria-label="Permalink to &quot;G) 共同帳本 CORS／cookie 冷啟動&quot;">​</a></h3><p>Cookie 只負責 restore；<code>canUseApi</code> 需要 access token。對照 <a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/google-backend-auth.md" target="_blank" rel="noreferrer"><code>docs/google-backend-auth.md</code></a>。</p><h3 id="h-play-看不到更新" tabindex="-1">H) Play 看不到更新 <a class="header-anchor" href="#h-play-看不到更新" aria-label="Permalink to &quot;H) Play 看不到更新&quot;">​</a></h3><p>AAB 上傳成功只代表檔案到 Google。確認 <code>play-testing-channel.json</code> 軌道、測試者 opt-in、以及 <code>https://www.strawmb.com/app-update.json</code> 的 <code>latestVersion</code>。<a href="/operations/wear-companion.html">Wear-Companion</a></p><h3 id="i-華南-hua-nan-account-list-not-found" tabindex="-1">I) 華南 <code>hua_nan_account_list_not_found</code> <a class="header-anchor" href="#i-華南-hua-nan-account-list-not-found" aria-label="Permalink to &quot;I) 華南 `hua_nan_account_list_not_found`&quot;">​</a></h3><p>H1 尚未用真實登入凍 DOM。<a href="/operations/sync-architecture-b.html">Sync-Architecture-B</a></p><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/.github/workflows/ci.yml" target="_blank" rel="noreferrer"><code>./.github/workflows/ci.yml</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/backend/scripts/deploy-production-install.mjs" target="_blank" rel="noreferrer"><code>backend/scripts/deploy-production-install.mjs</code></a></li></ul>',23)])])}const b=a(r,[["render",n]]);export{u as __pageData,b as default};
